import{_ as o,c as t,o as r,ag as a}from"./chunks/framework.DfL_BkQ-.js";const h=JSON.parse('{"title":"浏览器与嗅探器","description":"","frontmatter":{},"headers":[],"relativePath":"zh-CN/guide/browser.md","filePath":"zh-CN/guide/browser.md","lastUpdated":1791311600000}'),l={name:"zh-CN/guide/browser.md"};function d(i,e,c,n,s,g){return r(),t("div",null,[...e[0]||(e[0]=[a('<h1 id="浏览器与嗅探器" tabindex="-1">浏览器与嗅探器 <a class="header-anchor" href="#浏览器与嗅探器" aria-label="Permalink to &quot;浏览器与嗅探器&quot;">​</a></h1><p>nPlyr 内置一个基于 <code>WKWebView</code> 的真正的<strong>多标签浏览器</strong>，并带有<strong>媒体嗅探器</strong>。当你遇到一个不主动提供直链的页面时，它就是用来抓取直链的工具。</p><h2 id="浏览器" tabindex="-1">浏览器 <a class="header-anchor" href="#浏览器" aria-label="Permalink to &quot;浏览器&quot;">​</a></h2><p>这是一个 Chrome 风格的标签浏览器：</p><ul><li><strong>标签</strong>——新建 / 关闭 / 切换 / 重排；将标签拖出可成为独立窗口（macOS）。</li><li><strong>导航</strong>——后退、前进、刷新，以及带自动补全的地址栏。</li><li><strong>键盘快捷键</strong>——<code>⌘T</code> 新建标签、<code>⌘R</code> 刷新、<code>⌘[</code> / <code>⌘]</code> 后退 / 前进、<code>⌘L</code> 聚焦地址栏。</li><li><strong>拖放</strong>——将 URL 或文本拖入窗口即可打开。</li><li><strong>弹窗</strong>——<code>target=&quot;_blank&quot;</code> 与 <code>window.open</code> 会在新标签中打开，而不是被拦截。</li><li><strong>对话框</strong>——JS 的 <code>alert</code> / <code>confirm</code> / <code>prompt</code> 以原生方式呈现。</li><li><strong>下载</strong>——被拦截的下载链接会在应用内<strong>下载</strong>标签（<code>nplyr://downloads</code>）中打开。</li></ul><h2 id="嗅探器的工作原理" tabindex="-1">嗅探器的工作原理 <a class="header-anchor" href="#嗅探器的工作原理" aria-label="Permalink to &quot;嗅探器的工作原理&quot;">​</a></h2><p>页面加载时，nPlyr 会注入一个脚本，挂钩：</p><ul><li><code>fetch</code> 与 <code>XMLHttpRequest</code>，</li><li><code>video.src</code> 与 <code>HTMLMediaElement</code> 播放，</li><li><code>MediaSource</code> / <code>SourceBuffer.appendBuffer</code>。</li></ul><p>它还会通过 <code>WKNavigationDelegate</code> 监视导航，以捕获服务端媒体重定向。任何看起来像媒体文件的内容——<strong>m3u8 / mp4 / flv / ts</strong>——都会连同其<strong>请求头</strong>（referer、user-agent、cookie、auth）一起被收集到结果抽屉中。</p><p>在抽屉中你可以：</p><ul><li>立即在<a href="/zh-CN/guide/player.html">播放器</a>中<strong>播放</strong>该链接。</li><li>通过<a href="/zh-CN/guide/downloads.html">下载</a>将其<strong>下载</strong>（保留请求头）。</li><li><strong>复制</strong> URL 与请求头，以便在其他地方使用。</li></ul><blockquote><p>嗅探器只捕获页面实际请求的链接。使用专有播放器或重度 DRM 包裹视频流的站点可能不会暴露干净的直链——对于这类源，一个了解该源 API 的<a href="/zh-CN/guide/miniapps.html">小程序</a>是更可靠的路径。</p></blockquote><h2 id="已知限制" tabindex="-1">已知限制 <a class="header-anchor" href="#已知限制" aria-label="Permalink to &quot;已知限制&quot;">​</a></h2><p>以下项目是有意降低优先级，可能在后续版本中提供：</p><ul><li>页内右键菜单项（&quot;在新标签打开链接&quot;、&quot;下载链接&quot;）——macOS 的 <code>WKUIDelegate</code> 右键菜单钩子是 iOS 专属的；nPlyr 目前依赖标签栏与工具栏。</li><li>页内<strong>查找</strong>（<code>⌘F</code>）——WebKit API 存在，但 UI 尚未接好。</li><li><strong>打印</strong>（<code>⌘P</code>）——WebKit 支持，但尚无菜单项。</li><li><code>⌘W</code> 在多个标签打开时会关闭整个窗口；按标签关闭正在规划中。</li><li>全面重启应用后，已打开的标签与历史<strong>不会</strong>恢复。</li></ul><h2 id="隐私" tabindex="-1">隐私 <a class="header-anchor" href="#隐私" aria-label="Permalink to &quot;隐私&quot;">​</a></h2><p>该浏览器是一个标准的 <code>WKWebView</code>。它不会注入自身的追踪器。Cookie 与本地存储都留在应用的容器内。完整说明请参阅<a href="/zh-CN/guide/privacy.html">隐私</a>。</p>',17)])])}const p=o(l,[["render",d]]);export{h as __pageData,p as default};
